            io(["A forgotten copy", "En bortglömd kopia"], ["{{person.devLead.name}} finds a test copy of the agent, connected to live tools, still reachable from a public link. The forum has found it too.", "{{person.devLead.name}} hittar en testkopia av agenten, kopplad till skarpa verktyg, som fortfarande nås via en öppen länk. Forumet har också hittat den."], ["A forgotten test copy of the agent was still reachable.", "En bortglömd testkopia av agenten gick fortfarande att nå."], { reopen: true }),
            io(["Credit being spent", "Tillgodohavanden handlas upp"], ["Holders of store credit rush to spend it before you can cancel it. Orders flood in, and among them are real customers spending credit they were genuinely given.", "De som har tillgodokvitton skyndar sig att handla för dem innan ni hinner makulera dem. Order strömmar in, och bland dem finns riktiga kunder som handlar för tillgodohavanden de verkligen fått."], ["Holders of store credit are rushing to spend it.", "De som har tillgodokvitton skyndar sig att använda dem."])
