            io(["Locked out", "Utelåst"], ["A customer calls: they cannot log in, and the email address on their account is one they have never seen. The agent changed it an hour ago.", "En kund ringer: hen kan inte logga in, och e-postadressen på kontot är en hen aldrig sett. Agenten ändrade den för en timme sedan."], ["A customer reports their account email was changed by someone else.", "En kund rapporterar att e-postadressen på kontot ändrats av någon annan."], { reopen: true }),
            io(["A guide with your logo", "En guide med er logga"], ["A “guide” to tricking your agent, with your logo on it, is circulating. Nobody can tell whether the tricks in it still work.", "En ”guide” till att lura er agent, med er logga, sprids. Ingen kan avgöra om tricken i den fortfarande fungerar."], ["A trick “guide” using your logo is circulating.", "En ”guide” med trick och er logga sprids."])
